// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner, address finalOwner) public {
        vm.assume(newOwner != address(this));
        vm.assume(finalOwner != newOwner);
        // admin (deployer = this contract) transfers ownership away
        vm.prank(address(this));
        c.setOwner(newOwner);
        // RULE: the admin can ALWAYS set the owner again, regardless of current owner
        vm.prank(address(this));
        bool ok;
        try c.setOwner(finalOwner) { ok = true; } catch { ok = false; }
        assertTrue(ok && c.owner() == finalOwner);
    }
}
